#ifndef HEAPTIMER_H
#define HEAPTIMER_H

#include <deque>
#include <functional>
#include <map>
#include <chrono>
#include <iostream>

namespace log {
class Logger;
typedef std::shared_ptr<Logger> Ptr;
}

namespace detail {

}

template <typename Key>
class HeapTimer {
public:
    using Clock = std::chrono::steady_clock;
    using TimeOutCallback = std::function<void(const Key&)>;

private:
    log::Logger::Ptr logger_; 
    std::unordered_map<Key, std::size_t> key_to_idx_; 
    std::deque<Node> nodes_; 

public:
    HeapTimer(log::Logger::Ptr logger = log::RootLogger()) : logger_(logger) {}

    void Adjust(const Key& key, Clock::duration expiration) {
        auto it = key_to_idx_.find(key);
        if (it != key_to_idx_.end()) {
            std::size_t index = it->second;
            nodes_[index].expiration = Clock::now() + expiration;
            // TODO: Re-heapify
        }
    }

    void Adjust(const Key& key, Clock::time_point expiration) {
        auto it = key_to_idx_.find(key);
        if (it != key_to_idx_.end()) {
            std::size_t index = it->second;
            nodes_[index].expiration = expiration;
            // TODO: Re-heapify
        }
    }

    void Push(const Key& key, Clock::duration expiration, TimeOutCallback callback) {
        if (key_to_idx_.count(key)) return;

        nodes_.emplace_back(key, Clock::now() + expiration, callback);
        std::size_t index = nodes_.size() - 1;
        key_to_idx_[key] = index;
        ShiftUp(index);
    }

    void Push(const Key& key, Clock::time_point expiration, TimeOutCallback callback) {
        if (key_to_idx_.count(key)) return;

        nodes_.emplace_back(key, expiration, callback);
        std::size_t index = nodes_.size() - 1;
        key_to_idx_[key] = index;
        ShiftUp(index);
    }

    void Tick() {
        while (!nodes_.empty()) {
            if (nodes_.front().Expired()) {
                Key key = nodes_.front().key;
                nodes_.front().callback(key);
                Pop();
            } else {
                break;
            }
        }
    }

    bool Remove(const Key& key) {
        auto it = key_to_idx_.find(key);
        if (it == key_to_idx_.end()) return false;

        std::size_t index = it->second;
        Swap(index, nodes_.size() - 1);
        nodes_.pop_back();
        key_to_idx_.erase(it);
        ShiftDown(index);
        return true;
    }

    void Invoke(const Key& key) {
        auto it = key_to_idx_.find(key);
        if (it != key_to_idx_.end()) {
            std::size_t index = it->second;
            nodes_[index].callback(key);
            Pop();
        }
    }

    Key Pop() {
        if (nodes_.empty()) throw std::runtime_error("Heap is empty");
        Key key = nodes_.front().key;
        Remove(key);
        return key;
    }

    void Clear() {
        nodes_.clear();
        key_to_idx_.clear();
    }

    bool Contain(const Key& key) const {
        return key_to_idx_.count(key) > 0;
    }

    bool Empty() const {
        return nodes_.empty();
    }

    std::size_t Size() const {
        return nodes_.size();
    }

    Clock::duration ToNextTick() const {
        if (nodes_.empty()) return Clock::infinity();

        Clock::time_point next_expiration = nodes_.front().expiration;
        return next_expiration - Clock::now();
    }

private:
    void ShiftUp(std::size_t index) {
        while (index > 0) {
            std::size_t parent_index = (index - 1) / 2;
            if (nodes_[index].expiration < nodes_[parent_index].expiration) {
                Swap(index, parent_index);
                index = parent_index;
            } else {
                break;
            }
        }
    }

    void ShiftDown(std::size_t index) {
        std::size_t size = nodes_.size();
        while (true) {
            std::size_t left_child_index = 2 * index + 1;
            std::size_t right_child_index = 2 * index + 2;
            std::size_t smallest = index;

            if (left_child_index < size && nodes_[left_child_index].expiration < nodes_[smallest].expiration) {
                smallest = left_child_index;
            }

            if (right_child_index < size && nodes_[right_child_index].expiration < nodes_[smallest].expiration) {
                smallest = right_child_index;
            }

            if (smallest != index) {
                Swap(index, smallest);
                index = smallest;
            } else {
                break;
            }
        }
    }

    void Swap(std::size_t i, std::size_t j) {
        nodes_[i].Swap(nodes_[j]);
        key_to_idx_[nodes_[i].key] = i;
        key_to_idx_[nodes_[j].key] = j;
    }

    struct Node {
        Key key;
        Clock::time_point expiration;
        TimeOutCallback callback;

        Node() : key{}, expiration{Clock::now()}, callback{nullptr} {}

        bool Expired() const {
            return Clock::now() >= expiration;
        }

        void Swap(Node& o) {
            std::swap(key, o.key);
            std::swap(expiration, o.expiration);
            std::swap(callback, o.callback);
        }
    };
};

#endif // HEAPTIMER_H
